exercises.starter:
function sortAsc(arr) {
  // return a new array sorted smallest-first
}

exercises.solution:
function sortAsc(arr) {
  return [...arr].sort((a, b) => a - b)
}

exercises.starter:
function sortDesc(arr) {
  // return a new array sorted largest-first
}

exercises.solution:
function sortDesc(arr) {
  return [...arr].sort((a, b) => b - a)
}

exercises.starter:
function sortByLength(arr) {
  // return a new array of the strings, shortest first
}

exercises.solution:
function sortByLength(arr) {
  return [...arr].sort((a, b) => a.length - b.length)
}

exercises.starter:
function sortByAbs(arr) {
  // return a new array ordered by distance from zero
}

exercises.solution:
function sortByAbs(arr) {
  return [...arr].sort((a, b) => Math.abs(a) - Math.abs(b))
}

exercises.starter:
function kSmallest(arr, k) {
  // return the k smallest numbers, sorted ascending
}

exercises.solution:
function kSmallest(arr, k) {
  return [...arr].sort((a, b) => a - b).slice(0, k)
}
